FORMATS_OK = {"JPEG", "PNG", "WEBP"}


# Notebook cell 0, source line 5
TAILLE_MAX = 10 * 1024 * 1024  # 10 Mo


# Notebook cell 0, source line 8
def verifier_image(chemin):
    """Retourne (valide, code_erreur, message)."""

    try:
        with open(chemin, "rb") as f:
            donnees = f.read()
    except FileNotFoundError:
        return False, "MISSING_MEDIA", "Aucune image reçue."
    except OSError as e:
        return False, "UNREADABLE_FILE", str(e)

    if len(donnees) == 0:
        return False, "MISSING_MEDIA", "Le fichier est vide."

    if len(donnees) > TAILLE_MAX:
        return False, "FILE_TOO_LARGE", "Image trop volumineuse (10 Mo max)."

    try:
        with PILImage.open(chemin) as image:
            format_image = image.format

            if format_image not in FORMATS_OK:
                return (
                    False,
                    "UNSUPPORTED_FORMAT",
                    f"Format {format_image} refusé (JPEG, PNG, WEBP seulement)."
                )

            image.verify()

        # Réouvrir l'image pour vérifier qu'elle peut être entièrement décodée.
        with PILImage.open(chemin) as image:
            image.load()

    except (UnidentifiedImageError, OSError, ValueError):
        return False, "UNREADABLE_FILE", "Image corrompue ou illisible."

    return True, None, "Image valide."


# Notebook cell 4, source line 3
EMAIL = re.compile(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+")


# Notebook cell 4, source line 4
TEL_INTERNATIONAL = re.compile(r"(?<!\w)(?:\+|00)\d{1,3}(?:[\s.-]?\(?\d{1,4}\)?){2,6}(?!\w)")


# Notebook cell 4, source line 5
TEL_FRANCE = re.compile(r"(?<!\d)0\d(?:[\s.-]?\d{2}){4}(?!\d)")


# Notebook cell 4, source line 6
TEL_TUNISIE = re.compile(r"(?<!\d)\d{2}[\s.-]?\d{3}[\s.-]?\d{3}(?!\d)")


# Notebook cell 4, source line 9
def masquer_texte(texte):
    """Retourne (texte_masque, nombre_d_emails, nombre_de_telephones)."""
    texte, nb_emails = EMAIL.subn("[EMAIL]", texte)

    nb_tel = 0
    for motif in (TEL_INTERNATIONAL, TEL_FRANCE, TEL_TUNISIE):
        texte, n = motif.subn("[TELEPHONE]", texte)
        nb_tel += n

    return texte, nb_emails, nb_tel


