MODELES = ["gemini-3.8-flash", "gemini-3.5-flash-lite"]  # le 2e sert de secours


# Notebook cell 8, source line 30
def appeler_gemini(client, types, texte):
    """Appelle Gemini ; réessaie si le serveur est surchargé, puis passe au modèle de secours."""
    derniere_erreur = None
    for modele in MODELES:
        for essai in range(3):
            try:
                return client.models.generate_content(
                    model=modele,
                    contents=f"<report_text>\n{texte}\n</report_text>",
                    config=types.GenerateContentConfig(
                        system_instruction=PROMPT,       # = prompt système
                        max_output_tokens=2000,          # plafond de la réponse
                        response_mime_type="application/json",
                    ),
                )
            except Exception as erreur:
                derniere_erreur = erreur
                code = getattr(erreur, "code", None)
                if code in (429, 500, 503, 504):         # surcharge temporaire : on attend et on réessaie
                    if essai < 2:
                        time.sleep(2 ** (essai + 1))     # 2 s puis 4 s
                    continue
                if code == 404:                          # modèle introuvable : on passe au suivant
                    break
                raise                                    # autre erreur (clé refusée...) : inutile de réessayer
    raise derniere_erreur


# Notebook cell 8, source line 58
def nettoyer_texte(texte, client=None):
    """Retourne un dict {language, cleaned_text, text_quality}. Ne plante jamais."""
    try:
        from google.genai import types

        if client is None:
            from google import genai
            client = get_client()  # lit la variable GEMINI_API_KEY

        reponse = appeler_gemini(client, types, texte)
        brut = reponse.text
        resultat = json.loads(re.search(r"\{.*\}", brut, re.DOTALL).group(0))

        # Vérifier que la réponse a la bonne forme
        assert resultat["text_quality"] in QUALITES
        assert isinstance(resultat["cleaned_text"], str)
        assert isinstance(resultat["language"], str)
        return {"language": resultat["language"],
                "cleaned_text": resultat["cleaned_text"],
                "text_quality": resultat["text_quality"]}

    except Exception as erreur:
        # Plan B : sans LLM, on nettoie juste les espaces
        propre = re.sub(r"\s+", " ", texte).strip()
        return {"language": "unknown",
                "cleaned_text": propre,
                "text_quality": "EMPTY" if not propre else "CLEAR",
                "avertissement": f"LLM indisponible : {erreur!r}"}


# Notebook cell 12, source line 4
def flouter_visages(chemin_entree, chemin_sortie, modele="yunet.onnx"):
    """Floute les visages de l'image et l'enregistre dans un NOUVEAU fichier.
    Retourne le nombre de visages floutés."""
    modele = str(face_model_path())
    image = cv2.imread(chemin_entree)
    if image is None:
        raise ValueError("Image illisible")
    hauteur, largeur = image.shape[:2]

    # 1. Détecter les visages
    detecteur = cv2.FaceDetectorYN.create(modele, "", (largeur, hauteur), 0.6, 0.3, 5000)
    _, visages = detecteur.detect(image)
    if visages is None:
        visages = []  # aucun visage trouvé

    # 2. Flouter chaque visage
    for visage in visages:
        x, y, w, h = [int(v) for v in visage[:4]]
        marge_x, marge_y = int(w * 0.25), int(h * 0.25)  # on élargit un peu la zone
        x0, y0 = max(0, x - marge_x), max(0, y - marge_y)
        x1, y1 = min(largeur, x + w + marge_x), min(hauteur, y + h + marge_y)

        zone = image[y0:y1, x0:x1]
        petit = cv2.resize(zone, (max(1, (x1 - x0) // 12), max(1, (y1 - y0) // 12)), interpolation=cv2.INTER_AREA)
        pixels = cv2.resize(petit, (x1 - x0, y1 - y0), interpolation=cv2.INTER_NEAREST)  # pixellisation
        k = max(15, ((x1 - x0) // 3) | 1)                                                 # taille du flou (impair)
        image[y0:y1, x0:x1] = cv2.GaussianBlur(pixels, (k, k), 0)

    # 3. Enregistrer dans un autre fichier (l'original n'est pas modifié)
    if not cv2.imwrite(chemin_sortie, image):
        raise ValueError("Ecriture image traitee impossible")
    record_processed(chemin_entree, chemin_sortie, len(visages))
    return len(visages)


