# Notebook cell 18, source line 21
def generer(client, contents, config):
    """Appelle Gemini ; réessaie si le serveur est surchargé, puis passe au modèle de secours."""
    derniere_erreur = None
    for modele in MODELES:
        for essai in range(3):
            try:
                return client.models.generate_content(model=modele, contents=contents, config=config)
            except Exception as erreur:
                derniere_erreur = erreur
                code = getattr(erreur, "code", None)
                if code in (429, 500, 503, 504):
                    if essai < 2:
                        time.sleep(2 ** (essai + 1))
                    continue
                if code == 404:
                    break
                raise
    raise derniere_erreur


# Notebook cell 18, source line 41
def convertir_en_wav(chemin_audio, chemin_wav="audio.wav", duree_max=120):
    """Convertit n'importe quel audio en WAV mono 16 kHz (et vérifie qu'il est lisible)."""
    if not os.path.exists(chemin_audio) or os.path.getsize(chemin_audio) == 0:
        raise ValueError("Fichier audio absent ou vide")
    chemin_wav = str(work_path("audio_" + os.urandom(8).hex() + ".wav"))
    resultat = run_media_command(
        ["ffmpeg", "-y", "-v", "error", "-i", chemin_audio, "-t", str(duree_max),
         "-vn", "-ac", "1", "-ar", "16000", chemin_wav],
        capture_output=True)
    if resultat.returncode != 0 or not os.path.exists(chemin_wav):
        raise ValueError("Audio illisible ou corrompu")
    return chemin_wav


# Notebook cell 18, source line 54
def transcrire_audio(chemin_audio, client=None):
    """Retourne {"transcription": "..."}. Ne plante jamais : en cas de problème, transcription vide + avertissement."""
    try:
        wav = convertir_en_wav(chemin_audio)
        with open(wav, "rb") as f:
            donnees = f.read()

        if client is None:
            from google import genai
            client = get_client()  # lit GEMINI_API_KEY

        reponse = generer(
            client,
            contents=[types.Part.from_bytes(data=donnees, mime_type="audio/wav")],  # l'audio = message utilisateur
            config=types.GenerateContentConfig(
                system_instruction=PROMPT_TRANSCRIPTION,   # = prompt système
                max_output_tokens=4000,
            ),
        )
        texte = (reponse.text or "").strip()
        if texte == "[AUCUNE_PAROLE]":
            return {"transcription": "", "avertissement": "Aucune parole détectée dans l'audio"}
        return {"transcription": texte}

    except Exception as erreur:
        return {"transcription": "", "avertissement": f"Transcription impossible : {erreur!r}"}


