def decrire_image(chemin_image, client=None):
    """Demande à Gemini de décrire le problème urbain visible sur l'image."""
    try:
        with open(chemin_image, "rb") as f:
            donnees = f.read()

        if client is None:
            from google import genai
            client = get_client()

        prompt = (
            "Tu es un agent d'intake municipal. Analyse cette image liée à un signalement citoyen. "
            "Décris précisément le problème urbain visible (ex: nid-de-poule, décharge sauvage, panneau endommagé...) "
            "en une ou deux phrases factuelles, sans inventer d'éléments."
        )

        reponse = client.models.generate_content(
            model="gemini-3.5-flash-lite", # ou votre modèle habituel
            contents=[
                types.Part.from_bytes(data=donnees, mime_type=checked_image_mime(chemin_image)),
                prompt
            ]
        )
        return {"description_image": (reponse.text or "").strip()}
    except Exception as e:
        return {"description_image": "", "avertissement": f"Analyse image impossible : {e!r}"}


# Notebook cell 29, source line 6
def _lancer(commande):
    return run_media_command(commande, capture_output=True)


# Notebook cell 29, source line 10
def extraire_video(chemin_video, dossier="video_out", nb_images=3, duree_max=60):
    """Extrait des images clés, applique le floutage des visages, et extrait la piste audio d'une vidéo.
    Retourne {"images": [...], "audio": chemin ou None, "erreur": message ou None}."""
    dossier = str(work_path("video_" + os.urandom(8).hex()))
    resultat = {"images": [], "audio": None, "erreur": None}

    # 1. Le fichier existe-t-il ?
    if not os.path.exists(chemin_video) or os.path.getsize(chemin_video) == 0:
        resultat["erreur"] = "Vidéo absente ou vide"
        return resultat

    # 2. Que contient-il ? (ffprobe lit les "pistes" du fichier)
    info = _lancer(["ffprobe", "-v", "error", "-show_streams", "-show_format", "-of", "json", chemin_video])
    if info.returncode != 0:
        resultat["erreur"] = "Vidéo illisible ou corrompue"
        return resultat
    infos = json.loads(info.stdout or b"{}")
    pistes = [p.get("codec_type") for p in infos.get("streams", [])]
    if "video" not in pistes:
        resultat["erreur"] = "Aucune piste vidéo dans ce fichier"
        return resultat
    duree = float(infos.get("format", {}).get("duration") or 0)
    if duree <= 0:
        resultat["erreur"] = "Durée de la vidéo inconnue"
        return resultat
    if duree > duree_max:
        resultat["erreur"] = f"Vidéo trop longue ({duree:.0f} s, maximum {duree_max} s)"
        return resultat

    os.makedirs(dossier, exist_ok=True)

    # 3. Images régulièrement réparties (25 %, 50 %, 75 % si nb_images = 3)
    for i in range(nb_images):
        instant = duree * (i + 1) / (nb_images + 1)
        chemin_image = os.path.join(dossier, f"image_{i + 1}.jpg")
        r = _lancer(["ffmpeg", "-y", "-v", "error", "-ss", f"{instant:.2f}", "-i", chemin_video,
                     "-frames:v", "1", "-q:v", "3", chemin_image])
        if r.returncode == 0 and os.path.exists(chemin_image):
            # Application directe du floutage sur l'image extraite
            try:
                chemin_floute = str(safe_image_path(chemin_image))
                flouter_visages(chemin_image, chemin_floute)
            except Exception as e:
                resultat["erreur"] = "Floutage video impossible"
                return resultat

            resultat["images"].append(chemin_floute)

    if not resultat["images"]:
        resultat["erreur"] = "Impossible d'extraire des images de la vidéo"
        return resultat

    # 4. Audio, s'il y en a un
    if "audio" in pistes:
        chemin_audio = os.path.join(dossier, "audio.mp3")
        r = _lancer(["ffmpeg", "-y", "-v", "error", "-i", chemin_video, "-vn", "-ac", "1", "-ar", "16000", chemin_audio])
        if r.returncode == 0 and os.path.exists(chemin_audio):
            resultat["audio"] = chemin_audio

    return resultat


