# Notebook cell 35, source line 85
def classifier_pertinence_municipale(texte):
    """Détermine si un texte décrit un problème municipal."""

    if not isinstance(texte, str) or not texte.strip():
        return {
            "pertinent": False,
            "categorie": "incertain",
            "justification": "Aucun texte à analyser."
        }

    prompt = f"""
Tu es un système de tri de signalements municipaux.

Analyse le texte suivant.

TEXTE :
{texte}

Catégories :
- voirie
- dechets
- eclairage_public
- signalisation
- eau_assainissement
- espace_vert
- securite_urbaine
- autre_municipal
- hors_sujet
- incertain

Règles :
1. Un nid-de-poule ou une route dégradée relève de la voirie.
2. Un tutoriel informatique sans rapport avec un problème
   municipal relève de hors_sujet.
3. Le texte doit décrire un problème municipal identifiable.
4. Un texte trop vague doit être classé incertain.
5. Le seul mot "route" ne suffit pas à établir un problème.
6. Une simple mention de lieu ne constitue pas nécessairement
   un signalement.
7. pertinent=True uniquement si un problème municipal
   identifiable est décrit.
8. N'invente aucun fait.
"""

    try:
        response = client.models.generate_content(
            model="gemini-3.5-flash-lite",
            contents=prompt,
            config={
                "response_mime_type": "application/json",
                "response_schema": ClassificationMunicipale
            }
        )

        resultat = response.parsed

        if resultat is None and response.text:
            resultat = ClassificationMunicipale.model_validate_json(
                response.text
            )

        if resultat is None:
            raise ValueError("Réponse de classification vide.")

        return resultat.model_dump()

    except Exception as e:
        print("Erreur classification municipale :", e)

        return {
            "pertinent": False,
            "categorie": "incertain",
            "justification": (
                "Classification indisponible ; vérification nécessaire."
            )
        }


# Notebook cell 35, source line 167
def valider_coherence_multimodale(
    texte_citoyen="",
    description_image="",
    descriptions_images_video=None,
    transcription_audio="",
    transcription_video="",
    classification_citoyen=None,
    classification_audio=None,
    classification_video=None,
    image_presente=False,
    audio_independant_present=False,
    video_presente=False,
    audio_video_present=False
):
    """
    Évalue la cohérence globale et attribue un statut individuel
    à chaque média fourni.
    """

    descriptions_images_video = descriptions_images_video or []

    medias = []

    # L'image indépendante est évaluée même si sa description
    # a échoué : elle sera alors probablement insuffisante.
    if image_presente:
        medias.append({
            "id_media": "image_independante",
            "type": "image",
            "contenu": description_image or "Description indisponible."
        })

    # Chaque image vidéo est évaluée séparément.
    for index, element in enumerate(descriptions_images_video, start=1):
        if not isinstance(element, dict):
            continue

        medias.append({
            "id_media": f"image_video_{index}",
            "type": "image_video",
            "contenu": (
                element.get("description")
                or element.get("erreur")
                or "Description indisponible."
            )
        })

    if audio_independant_present:
        medias.append({
            "id_media": "audio_independant",
            "type": "audio_independant",
            "contenu": (
                transcription_audio or "Transcription indisponible."
            )
        })

    if audio_video_present or (
        video_presente and transcription_video
    ):
        medias.append({
            "id_media": "audio_video",
            "type": "audio_video",
            "contenu": (
                transcription_video or "Transcription indisponible."
            )
        })

    # Sans aucune information sur le signalement ou ses médias,
    # aucune comparaison fiable n'est possible.
    if not (
        (isinstance(texte_citoyen, str) and texte_citoyen.strip())
        or medias
    ):
        return {
            "coherence_multimodale": "INFORMATION_INSUFFISANTE",
            "validation_humaine_requise": True,
            "motif": "Aucune information exploitable disponible.",
            "elements_confirmes": [],
            "elements_incoherents": [],
            "evaluations_medias": []
        }

    prompt = f"""
Tu es un système de contrôle qualité de signalements municipaux.

OBJECTIF
Distinguer :
- la pertinence municipale du signalement ;
- les médias qui soutiennent le problème ;
- les médias insuffisants pour le vérifier ;
- les médias hors sujet ;
- les médias réellement contradictoires.

TEXTE DU CITOYEN :
{texte_citoyen or "Non fourni"}

CLASSIFICATION DU TEXTE :
{json.dumps(classification_citoyen, ensure_ascii=False)}

CLASSIFICATION DE L'AUDIO INDÉPENDANT :
{json.dumps(classification_audio, ensure_ascii=False)}

CLASSIFICATION DE L'AUDIO VIDÉO :
{json.dumps(classification_video, ensure_ascii=False)}

MÉDIAS À ÉVALUER :
{json.dumps(medias, ensure_ascii=False, indent=2)}

STATUTS AUTORISÉS POUR CHAQUE MÉDIA :

1. CONFIRME :
Le média contient des éléments directement pertinents qui
soutiennent le problème décrit. Pour une transcription audio,
cela signifie qu'elle soutient la déclaration, et non que le
problème a été vérifié physiquement sur le terrain.

2. INSUFFISANT :
Le média ne permet ni de confirmer ni de réfuter le problème.
Exemple : une photo de cyclistes alors que le signalement concerne
un nid-de-poule qui n'est pas clairement visible.

3. HORS_SUJET :
Le média porte sur un sujet sans rapport avec le signalement.
Exemple : un tutoriel informatique pour un signalement de voirie.

4. CONTRADICTOIRE :
Le média contient des informations directement pertinentes
qui contredisent réellement le signalement.
L'absence du problème dans une image ne suffit pas à utiliser
ce statut. Vérifie également que les lieux, moments et événements
comparés sont bien les mêmes avant de conclure à une contradiction.

RÈGLES OBLIGATOIRES :

- Évalue chaque média séparément.
- Retourne exactement le même id_media que celui fourni.
- N'invente aucun média ni aucun id_media.
- Un média insuffisant ne prouve pas l'absence du problème.
- Ne considère pas automatiquement une image non pertinente
  comme une contradiction.
- Ne rejette pas un signalement municipal pertinent uniquement
  parce que ses médias sont insuffisants ou hors sujet.
- Une déclaration du citoyen ou une transcription audio ne
  constitue pas, à elle seule, une preuve visuelle du problème.
- Si le problème n'est pas vérifiable à partir des éléments
  fournis, recommande une validation humaine.
- Si des médias se contredisent réellement, explique pourquoi.
- Distingue les éléments qui soutiennent le signalement des
  éléments hors sujet ou contradictoires.
- Si les données sont insuffisantes, utilise
  INFORMATION_INSUFFISANTE ou PARTIELLEMENT_COHERENTE selon
  les informations réellement disponibles.
- N'invente aucun fait.

COHÉRENCE GLOBALE :
- COHERENTE : les sources disponibles sont compatibles et
  soutiennent le même signalement.
- PARTIELLEMENT_COHERENTE : certaines sources concordent, mais
  d'autres sont insuffisantes ou hors sujet.
- INCOHERENTE : il existe une contradiction réelle et importante.
- INFORMATION_INSUFFISANTE : les informations disponibles ne
  permettent pas d'évaluer suffisamment la cohérence.

Demande une validation humaine lorsqu'une incertitude importante,
une contradiction ou une insuffisance empêche une décision fiable.
"""

    try:
        response = client.models.generate_content(
            model="gemini-3.5-flash-lite",
            contents=prompt,
            config={
                "response_mime_type": "application/json",
                "response_schema": ValidationMultimodale
            }
        )

        resultat = response.parsed

        if resultat is None and response.text:
            resultat = ValidationMultimodale.model_validate_json(
                response.text
            )

        if resultat is None:
            raise ValueError("Réponse de validation vide.")

        data = resultat.model_dump()

        # Ne pas laisser disparaître un média de la réponse.
        evaluations = {
            item["id_media"]: item
            for item in data.get("evaluations_medias", [])
        }

        evaluations_finales = []

        for media in medias:
            media_id = media["id_media"]
            evaluation = evaluations.get(media_id)

            if evaluation is None:
                evaluation = {
                    "id_media": media_id,
                    "statut": "INSUFFISANT",
                    "justification": (
                        "Aucune évaluation exploitable n'a été retournée."
                    )
                }

            evaluations_finales.append(evaluation)

        data["evaluations_medias"] = evaluations_finales

        # Les statuts incertains ou hors sujet justifient une
        # vérification, sans entraîner automatiquement un rejet.
        statuts = {
            e["statut"] for e in evaluations_finales
        }

        if statuts.intersection({
            "INSUFFISANT",
            "HORS_SUJET",
            "CONTRADICTOIRE"
        }):
            data["validation_humaine_requise"] = True

        if data["coherence_multimodale"] in {
            "INCOHERENTE",
            "INFORMATION_INSUFFISANTE"
        }:
            data["validation_humaine_requise"] = True

        return data

    except Exception as e:
        print("Erreur validation multimodale :", e)

        # En cas d'erreur de Gemini, ne pas inventer une évaluation.
        return {
            "coherence_multimodale": "INFORMATION_INSUFFISANTE",
            "validation_humaine_requise": True,
            "motif": (
                "La validation automatique a échoué. "
                "Une vérification humaine est nécessaire."
            ),
            "elements_confirmes": [],
            "elements_incoherents": [],
            "evaluations_medias": [
                {
                    "id_media": media["id_media"],
                    "statut": "INSUFFISANT",
                    "justification": (
                        "Évaluation automatique indisponible."
                    )
                }
                for media in medias
            ]
        }


# Notebook cell 35, source line 437
def traiter_signalement(
    texte_citoyen=None,
    chemin_image=None,
    chemin_audio=None,
    chemin_video=None
):
    texte_original = (
        texte_citoyen.strip()
        if isinstance(texte_citoyen, str)
        else ""
    )

    # CONFIDENTIALITÉ : tout texte est masqué (e-mails, téléphones) AVANT
    # d'être envoyé à Gemini (classification, nettoyage, validation).
    texte_original, n_emails, n_tels = masquer_texte(texte_original)[:3]
    total_emails, total_tels = n_emails, n_tels

    transcription_audio = ""
    transcription_video = ""
    descriptions_images_video = []

    rapport = {
        "language": "unknown",
        "cleaned_text": "",
        "text_quality": "EMPTY",

        "description_image": "",
        "statut_image": None,

        "descriptions_images_video": [],

        "transcription_audio": "",
        "statut_audio_independant": None,

        "transcription_video": "",
        "statut_audio_video": None,

        "classification_citoyen": None,
        "classification_audio": None,
        "classification_video": None,

        "pertinence_municipale": "INCERTAINE",

        "audio_direct_hors_sujet": None,
        "audio_video_hors_sujet": None,
        "contenu_audio_hors_sujet": None,

        "validation_multimodale": None,
        "validation_humaine_requise": True,

        "images_traitees": [],
        "avertissements": []
    }

    # --------------------------------------------------------
    # A. EXTRACTION DE LA VIDÉO
    # --------------------------------------------------------

    images_video = []
    chemin_audio_video = None

    if chemin_video:
        try:
            res_video = extraire_video(chemin_video)

            if isinstance(res_video, dict):
                if res_video.get("erreur"):
                    rapport["avertissements"].append(
                        f"Erreur vidéo : {res_video['erreur']}"
                    )
                else:
                    images_video = res_video.get("images", []) or []
                    chemin_audio_video = res_video.get("audio")
                    rapport["images_traitees"].extend(images_video)
            else:
                rapport["avertissements"].append(
                    "Résultat d'extraction vidéo invalide."
                )

        except Exception as e:
            rapport["avertissements"].append(
                f"Extraction vidéo impossible : {e}"
            )

    # --------------------------------------------------------
    # B. TRANSCRIPTION DE L'AUDIO INDÉPENDANT
    # --------------------------------------------------------

    if chemin_audio:
        try:
            res_audio = transcrire_audio(chemin_audio)

            if isinstance(res_audio, dict):
                transcription_audio = str(
                    res_audio.get("transcription") or ""
                ).strip()

                if res_audio.get("avertissement"):
                    rapport["avertissements"].append(
                        str(res_audio["avertissement"])
                    )
            else:
                transcription_audio = str(res_audio or "").strip()

            transcription_audio, n_emails, n_tels = masquer_texte(transcription_audio)[:3]
            total_emails += n_emails
            total_tels += n_tels
            rapport["transcription_audio"] = transcription_audio

            if not transcription_audio:
                rapport["avertissements"].append(
                    "L'audio indépendant n'a pas fourni de transcription."
                )

        except Exception as e:
            rapport["avertissements"].append(
                f"Transcription audio impossible : {e}"
            )

    # --------------------------------------------------------
    # C. TRANSCRIPTION DE L'AUDIO DE LA VIDÉO
    # --------------------------------------------------------

    if chemin_audio_video:
        try:
            res_audio_video = transcrire_audio(chemin_audio_video)

            if isinstance(res_audio_video, dict):
                transcription_video = str(
                    res_audio_video.get("transcription") or ""
                ).strip()

                if res_audio_video.get("avertissement"):
                    rapport["avertissements"].append(
                        "Audio vidéo : "
                        + str(res_audio_video["avertissement"])
                    )
            else:
                transcription_video = str(
                    res_audio_video or ""
                ).strip()

            transcription_video, n_emails, n_tels = masquer_texte(transcription_video)[:3]
            total_emails += n_emails
            total_tels += n_tels
            rapport["transcription_video"] = transcription_video

            if not transcription_video:
                rapport["avertissements"].append(
                    "L'audio vidéo n'a pas fourni de transcription."
                )

        except Exception as e:
            rapport["avertissements"].append(
                f"Transcription de l'audio vidéo impossible : {e}"
            )

    # --------------------------------------------------------
    # D. CLASSIFICATION DU TEXTE
    # --------------------------------------------------------

    if texte_original:
        c = classifier_pertinence_municipale(texte_original)
        rapport["classification_citoyen"] = c

        if c["categorie"] == "incertain":
            rapport["pertinence_municipale"] = "INCERTAINE"
        elif c["pertinent"]:
            rapport["pertinence_municipale"] = "PERTINENTE"
        else:
            rapport["pertinence_municipale"] = "HORS_SUJET"

    # --------------------------------------------------------
    # E. CLASSIFICATION DES TRANSCRIPTIONS
    # --------------------------------------------------------

    if transcription_audio:
        c = classifier_pertinence_municipale(transcription_audio)
        rapport["classification_audio"] = c

        rapport["audio_direct_hors_sujet"] = (
            c["categorie"] == "hors_sujet"
            and c["pertinent"] is False
        )

    if transcription_video:
        c = classifier_pertinence_municipale(transcription_video)
        rapport["classification_video"] = c

        rapport["audio_video_hors_sujet"] = (
            c["categorie"] == "hors_sujet"
            and c["pertinent"] is False
        )

        rapport["contenu_audio_hors_sujet"] = (
            rapport["audio_video_hors_sujet"]
        )

    # Sans texte écrit, la pertinence vient de l'audio indépendant.
    if rapport["classification_citoyen"] is None and rapport["classification_audio"]:
        c = rapport["classification_audio"]
        if c["categorie"] == "incertain":
            rapport["pertinence_municipale"] = "INCERTAINE"
        elif c["pertinent"]:
            rapport["pertinence_municipale"] = "PERTINENTE"
        else:
            rapport["pertinence_municipale"] = "HORS_SUJET"

    if rapport["audio_direct_hors_sujet"] is True:
        rapport["avertissements"].append(
            "L'audio indépendant semble hors sujet."
        )

    if rapport["audio_video_hors_sujet"] is True:
        rapport["avertissements"].append(
            "L'audio de la vidéo semble hors sujet."
        )

    # --------------------------------------------------------
    # F. NETTOYAGE DU TEXTE
    # --------------------------------------------------------

    texte_source = " ".join(
        m.strip() for m in (texte_original, transcription_audio)
        if m and m.strip()
    )

    if texte_source:
        try:
            res = nettoyer_texte(texte_source)

            if isinstance(res, dict):
                rapport["language"] = res.get("language", "unknown")
                rapport["cleaned_text"] = res.get("cleaned_text", "")
                rapport["text_quality"] = res.get("text_quality", "EMPTY")

                if res.get("avertissement"):
                    rapport["avertissements"].append(
                        str(res["avertissement"])
                    )
            else:
                rapport["avertissements"].append(
                    "Résultat du nettoyage de texte invalide."
                )

        except Exception as e:
            rapport["avertissements"].append(
                f"Nettoyage du texte impossible : {e}"
            )

    # --------------------------------------------------------
    # G. TRAITEMENT DE L'IMAGE INDÉPENDANTE
    # --------------------------------------------------------

    if chemin_image:
        try:
            verification = verifier_image(chemin_image)

            if isinstance(verification, dict):
                valide = verification.get(
                    "valide", verification.get("valid", False)
                )
                code_err = verification.get(
                    "code_err", verification.get("code", "")
                )
                msg = verification.get(
                    "erreur", verification.get("message", "")
                )
            else:
                valide, code_err, msg = verification

            if not valide:
                rapport["avertissements"].append(
                    f"Image invalide ({code_err}) : {msg}"
                )
            else:
                dossier, nom_fich = os.path.split(chemin_image)
                nom_base, ext = os.path.splitext(nom_fich)

                chemin_floue = str(safe_image_path(chemin_image))

                try:
                    flouter_visages(chemin_image, chemin_floue)

                    if os.path.isfile(chemin_floue):
                        rapport["images_traitees"].append(chemin_floue)
                        image_a_decrire = chemin_floue
                    else:
                        image_a_decrire = None

                except Exception as e:
                    image_a_decrire = None
                    rapport["avertissements"].append(
                        f"Floutage image impossible : {e}"
                    )

                if image_a_decrire is None:
                    rapport["avertissements"].append(
                        "Image non envoyée à l'analyse : floutage des "
                        "visages indisponible."
                    )

                res_img = (
                    decrire_image(image_a_decrire) if image_a_decrire else ""
                )

                if isinstance(res_img, dict):
                    rapport["description_image"] = (
                        res_img.get("description_image")
                        or res_img.get("description")
                        or ""
                    )

                    if res_img.get("avertissement"):
                        rapport["avertissements"].append(
                            str(res_img["avertissement"])
                        )
                else:
                    rapport["description_image"] = str(res_img or "")

        except Exception as e:
            rapport["avertissements"].append(
                f"Traitement de l'image impossible : {e}"
            )

    # --------------------------------------------------------
    # H. ANALYSE DES IMAGES VIDÉO
    # --------------------------------------------------------

    for index, chemin_frame in enumerate(images_video, start=1):
        description = ""

        try:
            verification = verifier_image(chemin_frame)

            if isinstance(verification, dict):
                valide = verification.get(
                    "valide", verification.get("valid", False)
                )
                code_err = verification.get(
                    "code_err", verification.get("code", "")
                )
                msg = verification.get(
                    "erreur", verification.get("message", "")
                )
            else:
                valide, code_err, msg = verification

            if not valide:
                rapport["avertissements"].append(
                    f"Image vidéo {index} invalide "
                    f"({code_err}) : {msg}"
                )

                descriptions_images_video.append({
                    "image": chemin_frame,
                    "description": "",
                    "erreur": str(msg)
                })
                continue

            dossier, nom_fich = os.path.split(chemin_frame)
            nom_base, ext = os.path.splitext(nom_fich)

            chemin_frame_floue = str(safe_image_path(chemin_frame))

            try:
                flouter_visages(chemin_frame, chemin_frame_floue)

                if os.path.isfile(chemin_frame_floue):
                    rapport["images_traitees"].append(
                        chemin_frame_floue
                    )
                    frame_a_decrire = chemin_frame_floue
                else:
                    frame_a_decrire = None

            except Exception as e:
                frame_a_decrire = None
                rapport["avertissements"].append(
                    f"Floutage de l'image vidéo {index} impossible : {e}"
                )

            if frame_a_decrire is None:
                rapport["avertissements"].append(
                    f"Image vidéo {index} non envoyée à l'analyse : "
                    "floutage des visages indisponible."
                )

            res_frame = (
                decrire_image(frame_a_decrire) if frame_a_decrire else ""
            )

            if isinstance(res_frame, dict):
                description = (
                    res_frame.get("description_image")
                    or res_frame.get("description")
                    or ""
                )

                if res_frame.get("avertissement"):
                    rapport["avertissements"].append(
                        f"Image vidéo {index} : "
                        + str(res_frame["avertissement"])
                    )
            else:
                description = str(res_frame or "")

            descriptions_images_video.append({
                "image": chemin_frame,
                "description": description
            })

        except Exception as e:
            rapport["avertissements"].append(
                f"Analyse de l'image vidéo {index} impossible : {e}"
            )

            descriptions_images_video.append({
                "image": chemin_frame,
                "description": "",
                "erreur": str(e)
            })

    rapport["descriptions_images_video"] = descriptions_images_video

    # --------------------------------------------------------
    # I. VALIDATION MULTIMODALE ET STATUTS DES MÉDIAS
    # --------------------------------------------------------

    validation = valider_coherence_multimodale(
        texte_citoyen=texte_original,
        description_image=rapport["description_image"],
        descriptions_images_video=descriptions_images_video,
        transcription_audio=transcription_audio,
        transcription_video=transcription_video,
        classification_citoyen=rapport["classification_citoyen"],
        classification_audio=rapport["classification_audio"],
        classification_video=rapport["classification_video"],
        image_presente=bool(chemin_image),
        audio_independant_present=bool(chemin_audio),
        video_presente=bool(chemin_video),
        audio_video_present=bool(chemin_audio_video)
    )

    rapport["validation_multimodale"] = validation

    # Récupérer les statuts individuels.
    evaluations = {
        e["id_media"]: e
        for e in validation.get("evaluations_medias", [])
    }

    rapport["statut_image"] = (
        evaluations.get("image_independante", {}).get("statut")
    )

    rapport["statut_audio_independant"] = (
        evaluations.get("audio_independant", {}).get("statut")
    )

    rapport["statut_audio_video"] = (
        evaluations.get("audio_video", {}).get("statut")
    )

    for index, element in enumerate(
        rapport["descriptions_images_video"], start=1
    ):
        evaluation = evaluations.get(f"image_video_{index}", {})

        element["statut"] = evaluation.get(
            "statut", "INSUFFISANT"
        )
        element["justification_statut"] = evaluation.get(
            "justification",
            "Évaluation indisponible."
        )

    # Une erreur de traitement, une classification incertaine
    # ou une incohérence ne doit jamais effacer une demande
    # de validation humaine.
    rapport["validation_humaine_requise"] = (
        validation.get("validation_humaine_requise", True)
    )

    if validation["coherence_multimodale"] in {
        "INCOHERENTE",
        "INFORMATION_INSUFFISANTE"
    }:
        rapport["validation_humaine_requise"] = True

        rapport["avertissements"].append(
            "La cohérence multimodale ne peut pas être établie "
            "de manière suffisamment fiable."
        )

    if any(
        e.get("statut") in {
            "INSUFFISANT",
            "HORS_SUJET",
            "CONTRADICTOIRE"
        }
        for e in validation.get("evaluations_medias", [])
    ):
        rapport["validation_humaine_requise"] = True

    if (
        rapport["pertinence_municipale"] == "PERTINENTE"
        and rapport["audio_video_hors_sujet"] is True
    ):
        rapport["validation_humaine_requise"] = True

        rapport["avertissements"].append(
            "Le signalement est pertinent, mais l'audio vidéo "
            "semble hors sujet."
        )

    # --------------------------------------------------------
    # J. MASQUAGE DES DONNÉES PERSONNELLES
    # --------------------------------------------------------

    if rapport["cleaned_text"]:
        try:
            res_masquage = masquer_texte(rapport["cleaned_text"])

            if isinstance(res_masquage, dict):
                texte_masque = (
                    res_masquage.get("texte_masque")
                    or res_masquage.get("cleaned_text")
                    or ""
                )

                nb_emails = res_masquage.get(
                    "emails_masques",
                    res_masquage.get("nb_emails", 0)
                )

                nb_tels = res_masquage.get(
                    "telephones_masques",
                    res_masquage.get("nb_tels", 0)
                )

            elif isinstance(res_masquage, (tuple, list)):
                texte_masque = (
                    res_masquage[0]
                    if len(res_masquage) > 0 else ""
                )
                nb_emails = (
                    res_masquage[1]
                    if len(res_masquage) > 1 else 0
                )
                nb_tels = (
                    res_masquage[2]
                    if len(res_masquage) > 2 else 0
                )
            else:
                texte_masque = str(res_masquage or "")
                nb_emails = 0
                nb_tels = 0

            rapport["cleaned_text"] = texte_masque

            if nb_emails or nb_tels:
                rapport["avertissements"].append(
                    f"Données masquées ({nb_emails} email(s), "
                    f"{nb_tels} téléphone(s))."
                )

        except Exception as e:
            rapport["avertissements"].append(
                f"Masquage des données personnelles impossible : {e}"
            )
            rapport["validation_humaine_requise"] = True

    if total_emails or total_tels:
        rapport["avertissements"].append(
            f"Données masquées ({total_emails} email(s), "
            f"{total_tels} téléphone(s))."
        )

    # Supprimer les avertissements dupliqués.
    rapport["avertissements"] = list(
        dict.fromkeys(rapport["avertissements"])
    )

    return rapport


# Notebook cell 35, source line 1044
class RequeteSignalement(BaseModel):
    texte: Optional[str] = None
    chemin_image: Optional[str] = None
    chemin_audio: Optional[str] = None
    chemin_video: Optional[str] = None
